package vision

// Generated by scripts/aikit_surface/step4_fix.py; regenerated on each run.

import "github.com/townsendmerino/aikit/linalg"

// aikitMatmulW8A8 is dst[M, N] = a[M, K] · Wᵀ for int8 weights q [N, K] with per-row scales, W8A8 (int8 activations): what linalg.MatmulBTW8A8
// computed, through a WeightMat over the same slices (aikit LS6 unexported the raw-slice form).
func aikitMatmulW8A8(a []float32, q []int8, scales, dst []float32, M, K, N int) {
	w := linalg.WrapInt8(q, scales, N, K, true)
	w.MatmulBT(a, dst, M)
}
